import { useEffect, useState } from 'react'
import { db } from '@/db/db'

/**
 * Holiday data packs (CAL-03).
 *
 * Official dates are never hard-coded into a component and never guessed. A
 * pack ships per year with a `source` string on every entry; dates that
 * Indonesia re-decides annually (SKB 3 Menteri) are deliberately absent rather
 * than approximated — a wrong red date is worse than a missing one.
 *
 * Packs are cached in IndexedDB after first fetch, so they work offline, and
 * users can import a replacement pack from Settings.
 */

export interface Holiday {
  date: string
  name: string
  official: boolean
  source: string
}

interface Pack {
  country: string
  year: number
  packVersion: number
  note?: string
  official: { date: string; name: string; source: string }[]
  celebrations: { date: string; name: string; optional: boolean }[]
}

const cache = new Map<number, Holiday[]>()

export function useHolidays(year: number): Holiday[] {
  const [rows, setRows] = useState<Holiday[]>(() => cache.get(year) ?? [])

  useEffect(() => {
    let cancelled = false
    load(year).then((h) => {
      if (!cancelled) setRows(h)
    })
    return () => {
      cancelled = true
    }
  }, [year])

  return rows
}

export async function load(year: number): Promise<Holiday[]> {
  const cached = cache.get(year)
  if (cached) return cached

  const stored = await db.settings.get(`holidays.id.${year}`)
  if (stored) {
    const flat = flatten(stored.value as Pack)
    cache.set(year, flat)
    return flat
  }

  try {
    const res = await fetch(`${import.meta.env.BASE_URL}holidays/id-${year}.json`)
    if (!res.ok) throw new Error('pack tidak ada')
    const pack = (await res.json()) as Pack
    await db.settings.put({ key: `holidays.id.${year}`, value: pack })
    const flat = flatten(pack)
    cache.set(year, flat)
    return flat
  } catch {
    // No pack for this year yet — the calendar simply shows no red dates.
    cache.set(year, [])
    return []
  }
}

/** Imports a user-supplied pack, replacing the stored one for that year. */
export async function importPack(raw: string): Promise<{ year: number; count: number }> {
  const pack = JSON.parse(raw) as Pack
  if (typeof pack.year !== 'number' || !Array.isArray(pack.official)) {
    throw new Error('File data hari libur ini nggak sesuai format TemuDua.')
  }
  await db.settings.put({ key: `holidays.id.${pack.year}`, value: pack })
  cache.delete(pack.year)
  return { year: pack.year, count: pack.official.length + (pack.celebrations?.length ?? 0) }
}

function flatten(pack: Pack): Holiday[] {
  return [
    ...pack.official.map((h) => ({ ...h, official: true })),
    ...(pack.celebrations ?? []).map((c) => ({
      date: c.date,
      name: c.name,
      official: false,
      source: 'Momen opsional',
    })),
  ]
}
